// Project-authored headless shim over the vendored ares SFC core (ISC).
//
// Exposes the same C ABI as the LakeSnes shims (crates/oracle/src/lib.rs
// `ffi` module) so the Rust boundary is unchanged: init/load/run/buttons/
// state + WRAM/VRAM/CGRAM/APU-RAM/CPU-PC accessors.
//
// The system pak (boards.bml + the SPC IPL) is injected from a header
// generated by crates/oracle/build.rs: "ares-embedded-data.hpp".

#include <ares/ares.hpp>
#include <sfc/sfc.hpp>
#include <nall/vfs.hpp>
#include <nall/hash/sha256.hpp>

#include <ares-embedded-data.hpp>

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <vector>

struct SnesCpuTraceEntry {
  uint32_t address;
  uint16_t directPage;
  uint8_t status;
  uint8_t dataBank;
  uint8_t emulation;
  uint8_t reserved[3];
};
static_assert(sizeof(SnesCpuTraceEntry) == 12);
static_assert(offsetof(SnesCpuTraceEntry, address) == 0);
static_assert(offsetof(SnesCpuTraceEntry, directPage) == 4);
static_assert(offsetof(SnesCpuTraceEntry, status) == 6);
static_assert(offsetof(SnesCpuTraceEntry, dataBank) == 7);
static_assert(offsetof(SnesCpuTraceEntry, emulation) == 8);

struct SnesCpuRegisters {
  uint32_t address;
  uint16_t accumulator;
  uint16_t x;
  uint16_t y;
  uint16_t stack;
  uint16_t directPage;
  uint8_t status;
  uint8_t dataBank;
  uint8_t emulation;
  uint8_t reserved[3];
};
static_assert(sizeof(SnesCpuRegisters) == 20);
static_assert(alignof(SnesCpuRegisters) == 4);
static_assert(offsetof(SnesCpuRegisters, address) == 0);
static_assert(offsetof(SnesCpuRegisters, accumulator) == 4);
static_assert(offsetof(SnesCpuRegisters, x) == 6);
static_assert(offsetof(SnesCpuRegisters, y) == 8);
static_assert(offsetof(SnesCpuRegisters, stack) == 10);
static_assert(offsetof(SnesCpuRegisters, directPage) == 12);
static_assert(offsetof(SnesCpuRegisters, status) == 14);
static_assert(offsetof(SnesCpuRegisters, dataBank) == 15);
static_assert(offsetof(SnesCpuRegisters, emulation) == 16);
static_assert(offsetof(SnesCpuRegisters, reserved) == 17);

static constexpr uint32_t CpuTraceInstructionLimit = 2'000'000;
static constexpr int SramSize = 8 * 1024;
static_assert(SramSize == 8192);
static_assert(sizeof(uint8_t) == 1);

namespace ares::SuperFamicom {
  auto load(Node::System&, string) -> bool;
  auto option(string, string) -> bool;
}

using namespace ares;

namespace {

// Screen::refreshPalette supplies ARGB8888, not RGB30.
constexpr uint32_t xrgb8888(uint32_t value) {
  return value & 0x00ffffff;
}
static_assert(xrgb8888(0xff112233) == 0x00112233, "video channels must be preserved");
static_assert(xrgb8888(0xffff0000) == 0x00ff0000, "red must remain red");
static_assert(xrgb8888(0xff000000) == 0x00000000, "alpha must not contaminate black");

struct OraclePlatform : ares::Platform {
  std::shared_ptr<vfs::directory> systemPak;
  std::vector<u8> romBytes;
  std::vector<u8> sramBytes;
  string bootTitle;
  string bootRegion;
  string bootBoard;

  bool buttonState[12] = {};

  u32 width = 0;
  u32 height = 0;
  std::vector<u32> lastFrame;

  bool systemAttached = false;

  SnesCpuTraceEntry* traceOutput = nullptr;
  uint32_t traceCount = 0;
  uint32_t traceTarget = 0;
  uint32_t traceLimit = 0;
  int traceStop = -1;
  Event lastEvent = Event::None;

  auto event(Event event) -> void override {
    lastEvent = event;
  }

  auto stopTrace(int reason, bool exitScheduler) -> void {
    traceStop = reason;
    traceOutput = nullptr;
    SuperFamicom::cpu.debugger.tracer.instruction->setEnabled(false);
    if(exitScheduler) SuperFamicom::scheduler.exit(Event::Step);
  }

  auto beginTrace(uint32_t target, uint32_t limit, SnesCpuTraceEntry* output) -> void {
    traceOutput = output;
    traceCount = 0;
    traceTarget = target;
    traceLimit = limit;
    traceStop = -1;
    auto& tracer = SuperFamicom::cpu.debugger.tracer.instruction;
    tracer->setMask(false);
    tracer->setDepth(0);
    tracer->setEnabled(true);
  }

  auto log(Node::Debugger::Tracer::Tracer node, string_view message) -> void override {
    (void)message;
    auto& tracer = SuperFamicom::cpu.debugger.tracer.instruction;
    if(traceStop >= 0 || node != tracer) return;

    auto& registers = SuperFamicom::cpu.r;
    traceOutput[traceCount++] = {
      (uint32_t)registers.pc.d,
      (uint16_t)registers.d.w,
      (uint8_t)(uint32_t)registers.p,
      (uint8_t)registers.b,
      (uint8_t)registers.e,
      {},
    };

    if((uint32_t)registers.pc.d == traceTarget) {
      stopTrace(0, true);
    } else if(traceCount >= traceLimit) {
      stopTrace(1, true);
    }
  }

  auto pak(Node::Object node) -> std::shared_ptr<vfs::directory> override {
    (void)node;
    if(!systemAttached) {
      systemAttached = true;
      return systemPak;
    }
    auto cart = std::make_shared<vfs::directory>();
    cart->setAttribute("title", bootTitle);
    cart->setAttribute("region", bootRegion);
    cart->setAttribute("board", bootBoard);
    cart->append("program.rom", std::span<const u8>{romBytes.data(), romBytes.size()});
    cart->append("save.ram", std::span<const u8>{sramBytes.data(), sramBytes.size()});
    return cart;
  }

  auto video(Node::Video::Screen, const u32* data, u32 pitch, u32 width, u32 height) -> void override {
    // Discard ares ARGB8888 alpha for the public XRGB8888 image.
    this->width = width;
    this->height = height;
    lastFrame.assign((std::size_t)width * height, 0);
    u32 sourceX = width > 512 ? (width - 512) / 2 : 0;
    u32 copyWidth = width > 512 ? 512 : width;
    u32 copyHeight = height > 480 ? 480 : height;
    u32 sourceY = height > 480 ? (height - 480) / 2 : 0;
    for(u32 y = 0; y < copyHeight; y++) {
      const u32* src = data + (y + sourceY) * (pitch >> 2) + sourceX;
      for(u32 x = 0; x < copyWidth; x++) {
        lastFrame[y * width + x] = xrgb8888(src[x]);
      }
    }
  }

  auto input(Node::Input::Input node) -> void override {
    static constexpr const char* names[12] = {
      "B", "Y", "Select", "Start", "Up", "Down", "Left", "Right", "A", "X", "L", "R",
    };
    auto name = node->name();
    for(u32 id : range(12)) {
      if(name == names[id]) {
        auto button = node->cast<Node::Input::Button>();
        if(button) button->setValue(buttonState[id]);
        return;
      }
    }
  }

  auto audio(Node::Audio::Stream) -> void override {}
};

class OracleCore;

namespace {
OracleCore* singletonCore = nullptr;
}

class OracleCore {
public:
  OraclePlatform platform;
  Node::System root;
  u32 frames = 0;
  bool loaded = false;

  OracleCore() {
    platform.systemPak = std::make_shared<vfs::directory>();
    platform.systemPak->append("boards.bml", std::span<const u8>{gBoardsBml, gBoardsBmlSize});
    platform.systemPak->append("ipl.rom", std::span<const u8>{gIplRom, 64});
  }

  bool loadRom(const u8* data, u32 length, const u8* sramData, u32 sramLength) {
    if(root && root->name()) {
      // Full teardown before reload: the ares core is a process singleton.
      root->unload();
    }
    root = {};
    // Copy both caller-owned buffers before attaching or powering the machine.
    platform.romBytes.assign(data, data + length);
    platform.sramBytes.assign(sramData, sramData + sramLength);
    // Region sniff from the SNES internal header.
    bool pal = platform.romBytes.size() > 0xffd9 && platform.romBytes[0xffd9] == 2;
    platform.bootRegion = pal ? "PAL" : "NTSC";
    platform.bootTitle = "Terranigma";
    platform.bootBoard = "SHVC-1J3M-20";

    SuperFamicom::option("Pixel Accuracy", true);
    SuperFamicom::option("Deterministic Entropy", true);

    ares::platform = (ares::Platform*)&platform;
    bool ok = SuperFamicom::load(root, string{"[Nintendo] Super Famicom (", platform.bootRegion, ")"});
    if(!ok) return false;

    if(auto port = root->find<Node::Port>("Cartridge Slot")) {
      auto cartridge = port->allocate();
      port->connect();
    } else {
      return false;
    }
    if(auto port = root->find<Node::Port>("Controller Port 1")) {
      auto device = port->allocate("Gamepad");
      port->connect();
    }
    root->power();
    return true;
  }
};

}  // namespace

extern "C" {

typedef struct Snes Snes;

// The ares core is a process singleton (globals + threads inside the
// vendored engine) and cannot be destroyed and rebuilt safely, so exactly
// one `OracleCore` ever lives. `snes_free` is a no-op; a second
// `snes_loadRom` (after the first session leaked a fresh core) fails
// cleanly rather than corrupting the engine. Any second boot requires a
// new process, which is how the test suite runs its cross-boot checks.
Snes* snes_init(void) {
  if(!singletonCore) singletonCore = new OracleCore();
  return (Snes*)singletonCore;
}

void snes_free(Snes* snes) {
  // The ares machine is process-global and cannot be safely destroyed or
  // recreated. Intentionally retain the singleton until process exit.
  (void)snes;
}

void snes_reset(Snes* snes, bool hard) {
  (void)snes;
  (void)hard;
}

bool snes_loadRomWithSram(Snes* snes, const uint8_t* data, int length,
                          const uint8_t* sramData, int sramLength) {
  if(!snes || !data || length <= 0 || !sramData || sramLength != SramSize) return false;
  auto* core = (OracleCore*)snes;
  if(core->loaded) return false;  // one boot per process; see snes_init
  // Claim before entering ares: failed initialization is not safely retryable.
  core->loaded = true;
  return core->loadRom(data, (u32)length, sramData, (u32)sramLength);
}

bool snes_loadRom(Snes* snes, const uint8_t* data, int length) {
  static constexpr uint8_t ZeroedSram[SramSize] = {};
  return snes_loadRomWithSram(snes, data, length, ZeroedSram, SramSize);
}

void snes_runFrame(Snes* snes) {
  auto* core = (OracleCore*)snes;
  core->root->run();
  core->frames++;
}

int snes_traceUntil(Snes* snes, uint32_t target, uint32_t instructionLimit,
                    uint32_t frameLimit, SnesCpuTraceEntry* entries, uint32_t* count) {
  if(!snes || target > 0xffffff || instructionLimit == 0 ||
     instructionLimit > CpuTraceInstructionLimit || frameLimit == 0 || !entries || !count) {
    return -1;
  }

  auto* core = (OracleCore*)snes;
  auto& platform = core->platform;
  platform.beginTrace(target, instructionLimit, entries);
  uint32_t tracedFrames = 0;

  while(platform.traceStop < 0) {
    platform.lastEvent = Event::None;
    core->root->run();
    if(platform.traceStop >= 0) break;
    if(platform.lastEvent == Event::Frame) {
      core->frames++;
      if(++tracedFrames >= frameLimit) platform.stopTrace(2, false);
    }
  }

  *count = platform.traceCount;
  return platform.traceStop;
}

void snes_setPixelFormat(Snes* snes, int pixelFormat) {
  (void)snes;
  (void)pixelFormat;
}

void snes_setPixels(Snes* snes, uint8_t* pixelData) {
  auto& pl = ((OracleCore*)snes)->platform;
  if(pl.lastFrame.empty()) return;
  for(u32 y = 0; y < pl.height && y < 480; y++) {
    for(u32 x = 0; x < pl.width && x < 512; x++) {
      u32 v = pl.lastFrame[y * pl.width + x];
      std::size_t offset = ((std::size_t)y * 512 + x) * 4;
      pixelData[offset + 0] = v & 0xff;
      pixelData[offset + 1] = (v >> 8) & 0xff;
      pixelData[offset + 2] = (v >> 16) & 0xff;
      pixelData[offset + 3] = 0;
    }
  }
}

void snes_setSamples(Snes* snes, int16_t* sampleData, int samplesPerFrame) {
  (void)snes;
  (void)sampleData;
  (void)samplesPerFrame;
}

void snes_setButtonState(Snes* snes, int player, int button, bool pressed) {
  (void)player;
  if(!snes || button < 0 || button > 11) return;
  ((OracleCore*)snes)->platform.buttonState[button] = pressed;
}

int snes_saveState(Snes* snes, uint8_t* data) {
  auto& core = *(OracleCore*)snes;
  auto s = core.root->serialize(true);
  auto size = s.size();
  // 4-byte shim frame counter prefix so state round-trips fully.
  if(data && size + 4 <= (u32)4 * 1024 * 1024) {
    uint32_t f = core.frames;
    std::memcpy(data, &f, 4);
    std::memcpy(data + 4, s.data(), size);
  }
  return (int)size + 4;
}

bool snes_loadState(Snes* snes, const uint8_t* data, int size) {
  auto& core = *(OracleCore*)snes;
  if(size < 4) return false;
  uint32_t f = 0;
  std::memcpy(&f, data, 4);
  core.frames = f;
  auto s = serializer{data + 4, (u32)size - 4};
  return core.root->unserialize(s);
}

const uint8_t* snes_ram(const Snes* snes) {
  (void)snes;
  return (const uint8_t*)SuperFamicom::cpu.wram;
}

uint32_t snes_frames(const Snes* snes) {
  return ((const OracleCore*)snes)->frames;
}

uint64_t snes_cycles(const Snes* snes) {
  (void)snes;
  return 0;
}

const uint16_t* snes_vram(const Snes* snes) {
  (void)snes;
  return (const uint16_t*)SuperFamicom::ppuImpl.vram.data;
}

const uint16_t* snes_cgram(const Snes* snes) {
  (void)snes;
  return (const uint16_t*)SuperFamicom::ppuImpl.cgram;
}

void snes_cpu_registers(const Snes* snes, SnesCpuRegisters* output) {
  (void)snes;
  const auto& registers = SuperFamicom::cpu.r;
  *output = {
    (uint32_t)registers.pc.d,
    (uint16_t)registers.a.w,
    (uint16_t)registers.x.w,
    (uint16_t)registers.y.w,
    (uint16_t)registers.s.w,
    (uint16_t)registers.d.w,
    (uint8_t)(uint32_t)registers.p,
    (uint8_t)registers.b,
    (uint8_t)registers.e,
    {},
  };
}

uint16_t snes_cpu_pc(const Snes* snes) {
  (void)snes;
  return SuperFamicom::cpu.r.pc.w;
}

uint8_t snes_cpu_bank(const Snes* snes) {
  (void)snes;
  return SuperFamicom::cpu.r.pc.b;
}

const uint8_t* snes_apu_ram(const Snes* snes) {
  (void)snes;
  return (const uint8_t*)SuperFamicom::dsp.apuram;
}

}  // extern "C"
